def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[n - 1]

    opp_d = 0
    opp_c = 0
    my_d = 0

    c_after_d = 0
    d_after_d = 0
    c_after_c = 0
    d_after_c = 0

    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if a == 'D':
            my_d += 1

        if i > 0:
            prev_a = history[i - 1][0]
            if prev_a == 'D':
                if b == 'C':
                    c_after_d += 1
                else:
                    d_after_d += 1
            else:
                if b == 'C':
                    c_after_c += 1
                else:
                    d_after_c += 1

    w = 10
    if n < w:
        w = n

    rec_opp_d = 0
    rec_opp_c = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    provoked = False
    if n >= 2 and history[n - 2][0] == 'D':
        provoked = True

    hostile = False
    if opp_d_streak >= 5:
        hostile = True
    if rec_opp_c == 0 and opp_d >= max(3, w):
        hostile = True
    if rec_opp_d >= 8:
        hostile = True
    if rec_opp_d >= 6 and rec_opp_c <= 2:
        hostile = True
    if opp_d >= opp_c + 6 and opp_d >= 10:
        hostile = True
    if d_after_c >= 8 and rec_opp_d >= 6:
        hostile = True

    if hostile:
        return 'D'

    if opp_last == 'D':
        if provoked:
            if my_last == 'C':
                return 'C'
            if rec_opp_c > 0 and opp_d_streak <= 3 and my_d_streak <= 2:
                return 'C'
            return 'D'
        else:
            if my_d_streak >= 1 and my_d_streak <= 2 and rec_opp_c > 0 and opp_d_streak <= 2:
                return 'C'
            return 'D'

    if opp_c >= opp_d and d_after_d == 0 and c_after_d >= 1:
        if n >= 90:
            return 'D'
        if c_after_d >= 2 and rng.random() < 0.08:
            return 'D'

    if n == 98 and opp_last == 'C' and my_last == 'C' and opp_d == 0 and my_d == 0:
        return 'D'

    if my_last == 'D':
        return 'C'

    return 'C'
